import GBNF, { RuleType } from 'gbnf';

describe('Iteration', () => {
  test.for([
    ['root ::= "foo"', '', [{ type: 'char', value: [102] }]],
    ['root ::= "foo"', 'f', [{ type: 'char', value: [111] }]],
    ['root ::= "foo"', 'fo', [{ type: 'char', value: [111] }]],
    ['root ::= "foo"', 'foo', [{ type: 'end' }]],
    [
      'root ::= "foo" | "bar" ',
      '',
      [
        { type: 'char', value: [102] },
        { type: 'char', value: [98] },
      ],
    ],
    ['root ::= "foo" | "bar" ', 'f', [{ type: 'char', value: [111] }]],
    ['root ::= "foo" | "bar" ', 'fo', [{ type: 'char', value: [111] }]],
    ['root ::= "foo" | "bar" ', 'foo', [{ type: 'end' }]],
    ['root ::= "foo" | "bar" ', 'b', [{ type: 'char', value: [97] }]],
    ['root ::= "foo" | "bar" ', 'ba', [{ type: 'char', value: [114] }]],
    ['root ::= "foo" | "bar" ', 'bar', [{ type: 'end' }]],
    [
      'root ::= "foo" | "bar" | "baz"',
      'ba',
      [
        { type: 'char', value: [114] },
        { type: 'char', value: [122] },
      ],
    ],
    ['root ::= "["', '[', [{ type: 'end' }]],
    ['root ::= "]"', ']', [{ type: 'end' }]],
    ['root ::= "[]"', '[]', [{ type: 'end' }]],
    ['root ::= "{"', '{', [{ type: 'end' }]],
    ['root ::= "}"', '}', [{ type: 'end' }]],
    ['root ::= "{}"', '{}', [{ type: 'end' }]],
    ['root ::= "[{}]"', '[{}]', [{ type: 'end' }]],
    ['root ::= [^f] "o"', '', [{ type: 'char_exclude', value: [102] }]],
    ['root ::= [^f] "o"', 'a', [{ type: 'char', value: [111] }]],
    ['root ::= [^A-Z]', '', [{ type: 'char_exclude', value: [[65, 90]] }]],
    [
      'root ::= [^A-Z0-9]',
      '',
      [
        {
          type: 'char_exclude',
          value: [
            [65, 90],
            [48, 57],
          ],
        },
      ],
    ],
    [
      'root ::= [^A-Z0-9_-]',
      '',
      [{ type: 'char_exclude', value: [[65, 90], [48, 57], 95, 45] }],
    ],
    ['\nroot ::= foo\nfoo ::= "foo"', '', [{ type: 'char', value: [102] }]],
...TAIL...
          value: [34, 97, 98, 99, 100, 101, 102, 103, 104, [65, 90]],
        },
        { type: 'end' },
      ],
    ],
    [
      'root ::= ( [^abcdefgh] | [b-z])* ',
      'bcdefghzyxw0123ABCZ',
      [
        { type: 'char_exclude', value: [97, 98, 99, 100, 101, 102, 103, 104] },
        { type: 'char', value: [[98, 122]] },
        { type: 'end' },
      ],
    ],
  ] as [
    string,
    string,
    {
      type: string;
      value: number[];
    }[],
  ][])(
    'It returns parse state for a grammar and initial string (%#): `%s` `%s`',
    ([grammar, input, expected]) => {
      let state = GBNF(grammar);
      state = state.add(input);
      expect([...state]).toEqual(expected);
    }
  );
});
